import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Button,
  CircularProgress,
  Alert,
  useTheme,
  useMediaQuery,
} from '@mui/material';
import { Refresh } from '@mui/icons-material';
import Masonry from '@mui/lab/Masonry';

const Gallery = () => {
  const [galleryData, setGalleryData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [imageLoadingStates, setImageLoadingStates] = useState({});
  const [imageHeights, setImageHeights] = useState({});

  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  const isTablet = useMediaQuery(theme.breakpoints.down('md'));

  const SCRIPT_URL = 'https://script.google.com/macros/s/AKfycbwCsCCWEYQlkzPTlrcoXOib7znjmSgkEk9C3EOPwSoJAwqehXiq1aGYWggy2qX1_jc8/exec';

  const fetchGalleryData = async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await fetch(`${SCRIPT_URL}?t=${Date.now()}`);
      if (!response.ok) {
        throw new Error(`Failed to fetch: ${response.status}`);
      }
      const result = await response.json();
      if (result.success && result.data) {
        const transformedData = result.data
          .filter(item => item.imageUrl && item.imageUrl.trim() !== '')
          .map((item, index) => ({
            imageNo: item.imageNo ?? index + 1,
            fileName: item.fileName || `Image ${item.imageNo ?? index + 1}`,
            imageUrl: item.imageUrl.trim()
          }));
        setGalleryData(transformedData);
        
        // Initialize loading states for all images
        const initialLoadingStates = {};
        transformedData.forEach((item, index) => {
          initialLoadingStates[index] = true;
        });
        setImageLoadingStates(initialLoadingStates);
      } else {
        throw new Error(result.error || 'Failed to fetch data from server');
      }
    } catch (err) {
      setError(`Error loading gallery: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchGalleryData();
  }, []);

  const extractFileId = (url) => {
    if (!url) return null;
    const match = url.match(/\/d\/([a-zA-Z0-9_-]+)/) || url.match(/id=([a-zA-Z0-9_-]+)/);
    return match ? match[1] : null;
  };

  const getThumbnailUrl = (url) => {
    const fileId = extractFileId(url);
    return fileId ? `https://drive.google.com/thumbnail?id=${fileId}&sz=w400` : url;
  };

  const handleImageLoad = (index, event) => {
    const img = event.target;
    const height = img.naturalHeight;
    const width = img.naturalWidth;
    const aspectRatio = height / width;
    
    setImageHeights(prev => ({
      ...prev,
      [index]: aspectRatio
    }));
    
    setImageLoadingStates(prev => ({
      ...prev,
      [index]: false
    }));
  };

  const handleImageError = (index) => {
    setImageLoadingStates(prev => ({
      ...prev,
      [index]: false
    }));
  };

  // Determine columns based on screen size
  const getColumns = () => {
    if (isMobile) return 2;
    if (isTablet) return 3;
    return 4;
  };

  if (loading) {
    return (
      <Box 
        display="flex" 
        justifyContent="center" 
        alignItems="center" 
        minHeight="200px"
        flexDirection="column"
        gap={2}
      >
        <CircularProgress />
        <Typography variant="body1">Loading photos...</Typography>
      </Box>
    );
  }

  if (error) {
    return (
      <Box p={3} display="flex" flexDirection="column" alignItems="center" gap={2}>
        <Alert severity="error" sx={{ width: '100%', maxWidth: 400 }}>
          {error}
        </Alert>
        <Button 
          variant="contained" 
          startIcon={<Refresh />}
          onClick={fetchGalleryData}
        >
          Try Again
        </Button>
      </Box>
    );
  }

  return (
    <Box sx={{ p: { xs: 1, sm: 2, md: 3 }, maxWidth: 1200, margin: '0 auto' }}>
      <Typography 
        variant="h3" 
        component="h1" 
        align="center" 
        gutterBottom
        sx={{ 
          fontSize: { xs: '1.75rem', sm: '2.5rem', md: '3rem' },
          mb: 1 
        }}
      >
        Photo Gallery
      </Typography>
      
      <Typography 
        variant="h6" 
        component="p" 
        align="center" 
        color="text.secondary"
        sx={{ mb: 3 }}
      >
        {galleryData.length} {galleryData.length === 1 ? 'photo' : 'photos'}
      </Typography>

      {galleryData.length === 0 ? (
        <Typography variant="body1" align="center">
          No photos found.
        </Typography>
      ) : (
        <Masonry 
          columns={getColumns()} 
          spacing={2}
          sx={{ 
            margin: 0,
            '& .MuiMasonry-root': {
              margin: 0,
            }
          }}
        >
          {galleryData.map((item, idx) => (
            <Box
              key={idx}
              sx={{
                borderRadius: 2,
                overflow: 'hidden',
                boxShadow: 1,
                transition: 'all 0.3s ease',
                backgroundColor: 'background.paper',
                '&:hover': {
                  transform: 'translateY(-4px)',
                  boxShadow: 4,
                },
                position: 'relative',
              }}
            >
              {/* Loader */}
              {imageLoadingStates[idx] && (
                <Box
                  sx={{
                    position: 'absolute',
                    top: 0,
                    left: 0,
                    right: 0,
                    bottom: 0,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    backgroundColor: 'rgba(0,0,0,0.05)',
                    zIndex: 1,
                    minHeight: 200, // Temporary height for loader
                  }}
                >
                  <CircularProgress size={40} />
                </Box>
              )}
              
              <Box
                component="img"
                src={getThumbnailUrl(item.imageUrl)}
                alt={item.fileName}
                loading="lazy"
                sx={{
                  width: '100%',
                  display: 'block',
                  objectFit: 'cover',
                  opacity: imageLoadingStates[idx] ? 0 : 1,
                  transition: 'opacity 0.3s ease',
                }}
                onLoad={(e) => handleImageLoad(idx, e)}
                onError={() => handleImageError(idx)}
              />
            </Box>
          ))}
        </Masonry>
      )}
    </Box>
  );
};

export default Gallery;
